package pe.cruzroja.convocatorias.users.domain;
import java.util.UUID; import java.util.regex.Pattern;
public class User { private static final Pattern EMAIL=Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"); private final UUID id; private final String name,email,passwordHash; private final UserRole role; private final boolean graduated; private UserStatus status;
 public User(UUID id,String name,String email,String passwordHash,UserRole role,boolean graduated,UserStatus status){if(id==null||name==null||name.isBlank()||email==null||!EMAIL.matcher(email).matches()||passwordHash==null||passwordHash.isBlank()||role==null||status==null)throw new IllegalArgumentException("Datos de usuario inválidos");this.id=id;this.name=name.trim();this.email=email.toLowerCase();this.passwordHash=passwordHash;this.role=role;this.graduated=graduated;this.status=status;} public boolean canLogin(){return status==UserStatus.ACTIVO;} public boolean canManageCallouts(){return role==UserRole.JEFATURA||(role==UserRole.RECLUTADOR&&graduated);} public UUID id(){return id;} public String name(){return name;} public String email(){return email;} public String passwordHash(){return passwordHash;} public UserRole role(){return role;} public boolean graduated(){return graduated;} public UserStatus status(){return status;} }
